from collections import defaultdict

def rrf(lists, k=60):
    scores = defaultdict(float)
    for ranking in lists:
        for rank, doc in enumerate(ranking, start=1):
            scores[doc] += 1 / (k + rank)
    return sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))

vector = ["refunds", "returns", "warranty"]
keyword = ["sku-b08", "returns", "refunds"]
for doc, s in rrf([vector, keyword]):
    print(doc, round(s * 1000, 2))
print(rrf([vector, keyword], k=0)[0][0])
